  .nav__toggle {
    display: none;
  }

  .servicios__grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .quienes__contenido {
    flex-direction: row;
    align-items: center;
    gap: 3rem;
  }

  .quienes__imagen {
    width: 45%;
    flex-shrink: 0;
  }

  .quienes__texto {
    width: 55%;
  }

  .contacto__form {
    max-width: 600px;
    margin-inline: auto;
  }

  .form__fila-doble {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
  }

} /* cierre @media 48em */

/* ==========================================================================
   DESKTOP — min-width: 64em (1024px)
   ========================================================================== */

@media (min-width: 64em) {

  .contenedor {
    max-width: 1200px;
  }

  .hero__titulo {
    font-size: 3.5rem;
  }

  .hero__subtitulo {
    font-size: 1.25rem;
    max-width: 600px;
  }

  .servicios__grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .servicio__card {
    padding: 2.5rem;
  }

} /* cierre @media 64em */
